import { readFile, writeFile } from "node:fs/promises";
import { buildCompanionStatic } from "./build-companion-static.mjs";

// 从本仓库维护的形象源码生成；隔离命名空间，不依赖全局 window 或相邻仓库。
const root = new URL("../vendor/companion/", import.meta.url);
const order = JSON.parse(
  await readFile(new URL("source/order.json", root), "utf8"),
);
const styles = JSON.parse(await readFile(new URL("styles.json", root), "utf8"));
const parts = [
  "// Generated by node scripts/build-companion.mjs. Do not edit.",
  ...Object.keys(styles).flatMap((style) =>
    [256, 512].map(
      (size) =>
        `import ${style}${size} from "./assets/bodies/${style}-${size}.png";`,
    ),
  ),
  "const window = {};",
  "window.AllyBodies = {" +
    Object.entries(styles)
      .map(
        ([style, material]) =>
          `${style}: {...${JSON.stringify(material)}, images: {256: ${style}256, 512: ${style}512}}`,
      )
      .join(",") +
    "};",
];
for (const file of order) {
  parts.push(await readFile(new URL(`source/${file}`, root), "utf8"));
  if (file === "action-engine.js")
    parts.push("const AllyActionEngine = window.AllyActionEngine;");
}
parts.push(
  "// 互动目录直接取自实际注册的状态和动作，避免界面维护另一份状态编号。",
  "export const companionReactions = [",
  "  ...window.AllyStates.map(({ id, group }) => ({ id: 'state:' + id, emotion: id, group, duration: ['30', '37', '40'].includes(id) ? 4200 : 3200 })),",
  "  ...window.AllyActionEngine.list().map(({ name, emotion, duration }) => ({ id: 'action:' + name, emotion, group: 'action', action: name, duration: duration * 1000 + 200 })),",
  "  ...window.NeuxBot.idleEyeGestures.map(name => ({ id: 'gaze:' + name, emotion: '02', group: 'action', action: 'look:' + name, duration: 2900 })),",
  "];",
  "// 表情与身体共用状态事件；原型演示页承担的同步在此收口。",
  "export const createCompanion = (element, options) => {",
  "  const engine = window.NeuxBot.create(element, options);",
  "  engine.on('change', ({ id }) => engine.ball.setEmotion(id));",
  "  return engine;",
  "};\n",
);
const target = new URL("renderer.js", root);
const generated = parts.join("\n");
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== generated) {
    throw new Error(
      "形象渲染器与素材源码不一致，请运行 pnpm companion:generate",
    );
  }
} else {
  await writeFile(target, generated);
}

await buildCompanionStatic(
  root,
  styles,
  order,
  process.argv.includes("--check"),
);
